import unittest

from shipping.cost import shipping_cost
from shipping.models import Item


class ShippingCostTests(unittest.TestCase):
    def setUp(self):
        self.items = [Item("A", weight_kg=1.2), Item("B", weight_kg=0.4), Item("C", weight_kg=3.0)]

    def test_charges_per_kilo_plus_handling(self):
        expected = sum(item.weight_kg * 4.5 for item in self.items) + 7.0
        self.assertAlmostEqual(shipping_cost(self.items), expected)

    def test_empty_cart_is_free(self):
        self.assertEqual(shipping_cost([]), 0)

import pytest

from tools.config import parse_config_lines

SAMPLES = {
    "comments": ["# header", "  host=db  ", "port=5432"],
    "blank lines": ["", "user=app", "   ", "# trailing"],
    "only comments": ["# a", "# b"],
}


@pytest.mark.parametrize("name", list(SAMPLES))
def test_strips_comments_and_whitespace(name):
    lines = SAMPLES[name]
    expected = [line.strip() for line in lines if line.strip() and not line.strip().startswith("#")]
    assert parse_config_lines(lines) == expected

